using System.IO;
using System.Linq;
using System.Collections;
using UnityEditor;
using UnityEngine;
using UnityEngine.EventSystems;
[InitializeOnLoad] public static class StorybookRebirthEntryValidation
{
 const string Out=StorybookRebirthEntryFix.Out;static bool running;
 static StorybookRebirthEntryValidation(){EditorApplication.update+=Tick;EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredEditMode&&SessionState.GetBool("REBIRTH_ENTRY_QA",false)){running=false;SessionState.SetBool("REBIRTH_ENTRY_QA",false);SessionState.SetBool("MONSTER_QA_DISABLE_SAVE",false);}};}
 static void Tick(){if(EditorApplication.isCompiling||EditorApplication.isUpdating)return;if(!EditorApplication.isPlayingOrWillChangePlaymode&&File.Exists(Out+"validate.request")){File.Delete(Out+"validate.request");UnityEditor.SceneManagement.EditorSceneManager.OpenScene(EditorBuildSettings.scenes.First(s=>s.enabled).path);File.WriteAllText(Out+"validation.txt","");SessionState.SetBool("REBIRTH_ENTRY_QA",true);SessionState.SetBool("MONSTER_QA_DISABLE_SAVE",true);EditorApplication.isPlaying=true;}if(EditorApplication.isPlaying&&SessionState.GetBool("REBIRTH_ENTRY_QA",false)&&!running&&GameManager.single&&GameplayCanvas.single){running=true;GameManager.single.StartCoroutine(Run());}}
 static void Check(bool b,string s)=>File.AppendAllText(Out+"validation.txt",(b?"PASS ":"FAIL ")+s+"\n");
 static IEnumerator Run(){var intro=Object.FindAnyObjectByType<CursedBookIntro>();while(intro&&intro.gameObject.activeSelf)yield return null;yield return new WaitForSecondsRealtime(.5f);var gc=GameplayCanvas.single;var gm=GameManager.single;foreach(var d in Object.FindObjectsByType<DebugMenu>(FindObjectsInactive.Include,FindObjectsSortMode.None))d.enabled=false;var dev=Object.FindAnyObjectByType<DeveloperOverlayUI>();if(dev)dev.gameObject.SetActive(false);gc.CancelInvoke("TryShowingXpBoosterNotification");gc.xpBoosterNotification.SetActive(false);gc.dailyCherriesPop.SetActive(false);gc.GetComponent<StorybookDailyReward>().enabled=false;TutorialManager.single.automatic=false;TutorialManager.single.view.Hide();var h=gc.homeUI;
 gm.rebirthLevel=0;gm.playerLevel=1;h.Refresh();h.functionButtons[2].onClick.Invoke();yield return new WaitForSecondsRealtime(.3f);Check(h.modal.activeSelf&&!h.modalAction.interactable,"Locked condition still explains requirement");h.CloseModal();yield return new WaitForSecondsRealtime(.3f);gm.playerLevel=75;h.Refresh();
 foreach(var sz in new[]{new Vector2Int(1080,1920),new Vector2Int(768,1024),new Vector2Int(720,1440)}){StorybookEquipmentValidation.Resolution(sz.x,sz.y);h.functionButtons[2].onClick.Invoke();Check(!h.modal.activeSelf,"Ready button bypasses home prompt "+sz);yield return new WaitForSecondsRealtime(2);var r=RebirthPackage.single;Check(r&&r.view.gameObject.activeInHierarchy,"Rebirth UI opens directly "+sz);Check(Camera.allCameras.Any(c=>c.enabled&&c.gameObject.activeInHierarchy&&c.targetTexture==null&&c.targetDisplay==0),"Display 1 has active camera "+sz);Check(r.transform.Find("PresentationCamera").GetComponent<Camera>().cullingMask==0,"Presentation camera renders no world objects "+sz);Check(!r.AreYouSurePanel.activeSelf&&gm.rebirthLevel==0,"Entry does not execute rebirth or open confirmation "+sz);yield return new WaitForEndOfFrame();var t=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(Out+"rebirth-"+sz.x+"x"+sz.y+".png",t.EncodeToPNG());Object.Destroy(t);r.view.adventure.onClick.Invoke();yield return new WaitForSecondsRealtime(2);Check(!RebirthPackage.single&&h.gameObject.activeInHierarchy&&Camera.allCameras.Length>0,"Continue adventure restores home and camera "+sz);}
 File.AppendAllText(Out+"validation.txt","DONE\n");EditorApplication.isPlaying=false;}
}
